class entity;
class trigger;

class stringx {
    char *characters;
    void *buffer;
public:
    stringx();
    stringx(const stringx &);
    ~stringx();
};

stringx operator+(const stringx &, const char *);
stringx operator+(const stringx &, const stringx &);
void error(const stringx &);

class script_object {
public:
    const stringx &get_name() const;
};

class vm_executable {
public:
    const stringx &get_fullname() const;
};

class vm_thread {
    script_object *instance;
    vm_executable *executable;
public:
    script_object *get_instance() const { return instance; }
    vm_executable *get_executable() const { return executable; }
};

class vm_stack {
public:
    int salloc;
    char *buffer;
    char *SP;
private:
    vm_thread *my_thread;
public:
    void pop(int n) { SP -= n; }
    bool push(const char *, int);
    char *get_SP() const { return SP; }
    vm_thread *get_thread() const { return my_thread; }
};

class script_library_class {
public:
    class function {
    public:
        enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    };
};

class trigger_manager {
public:
    static trigger_manager *inst();
    trigger *new_box_trigger(entity *);
};

typedef entity *vm_entity_t;

class slf_create_box_trigger_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_entity_t e;
  };
  bool operator()( vm_stack& stack,entry_t entry );
};

extern trigger_manager *g_trigger_manager;
__asm__(".equ g_trigger_manager, 0x00431A88");
__asm__(".equ new_box_trigger__15trigger_managerP6entity, 0x0028D610");

trigger_manager *trigger_manager::inst()
{
  return g_trigger_manager;
}

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t *parms = (parms_t *)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )
#define SLF_DONE return true

bool slf_create_box_trigger_t::operator()( vm_stack& stack,entry_t entry )
{
  SLF_PARMS;
  trigger* result = trigger_manager::inst()->new_box_trigger( parms->e );
  SLF_RETURN;
  SLF_DONE;
}
